import {
  computed,
  effect,
  inject,
  Injectable,
  PLATFORM_ID,
  signal
} from '@angular/core';

import { isPlatformBrowser } from '@angular/common';

import { User } from '../interfaces/user.interface';

@Injectable({
  providedIn: 'root'
})
export class AuthStore {

  private platformId = inject(PLATFORM_ID);

  user = signal<User | null>(null);

  isAuthenticated = computed(() => !!this.user());

  constructor() {

    // SOLO EN BROWSER

    if (isPlatformBrowser(this.platformId)) {

      const savedUser = localStorage.getItem('user');

      if (savedUser) {
        this.user.set(JSON.parse(savedUser));
      }

      effect(() => {

        const currentUser = this.user();

        if (currentUser) {

          localStorage.setItem(
            'user',
            JSON.stringify(currentUser)
          );

        } else {

          localStorage.removeItem('user');

        }

      });

    }
  }

  login(email: string) {

    const mockUser: User = {
      id: crypto.randomUUID(),
      name: 'Joel User',
      email,
      avatar: 'https://i.pravatar.cc/150'
    };

    this.user.set(mockUser);
  }

  loginWithGoogle() {

    const mockUser: User = {
      id: crypto.randomUUID(),
      name: 'Google User',
      email: 'google@gmail.com',
      avatar: 'https://i.pravatar.cc/150'
    };

    this.user.set(mockUser);
  }

  logout() {

    this.user.set(null);

    if (isPlatformBrowser(this.platformId)) {
      localStorage.removeItem('user');
    }
  }
}

import {
  effect,
  inject,
  Injectable,
  PLATFORM_ID,
  signal
} from '@angular/core';

import { isPlatformBrowser } from '@angular/common';

import { Post } from '../../../shared/interfaces/post.interface';

import { Comment } from '../../../shared/interfaces/comment.interface';
import { MOCK_POSTS } from '../mock/post.mock';
import { AuthStore } from '../../auth/store/auth.store.service';


@Injectable({
  providedIn: 'root'
})
export class PostsStore {

  private platformId = inject(PLATFORM_ID);

  posts = signal<Post[]>([]);

  authStore = inject(AuthStore)

  constructor() {

    if (isPlatformBrowser(this.platformId)) {

      const savedPosts = localStorage.getItem('posts');

      if (savedPosts) {

        this.posts.set(JSON.parse(savedPosts));

      } else {

        this.posts.set(MOCK_POSTS);

      }

      effect(() => {

        localStorage.setItem(
          'posts',
          JSON.stringify(this.posts())
        );

      });

    } else {

      // SSR fallback

      this.posts.set(MOCK_POSTS);

    }
  }

  createPost(content: string) {

    const newPost: Post = {
      id: crypto.randomUUID(),
      author: this.authStore.user()?.name || 'Current User',
      content,
      likes: 0,
      createdAt: new Date(),
      comments: []
    };

    this.posts.update(posts => [
      newPost,
      ...posts
    ]);
  }

  addComment(
    postId: string,
    message: string
  ) {

    const comment: Comment = {
      id: crypto.randomUUID(),
      postId,
      author: this.authStore.user()?.name || 'Current User',
      message,
      createdAt: new Date()
    };

    this.posts.update(posts =>
      posts.map(post => {

        if (post.id === postId) {

          return {
            ...post,
            comments: [
              ...post.comments,
              comment
            ]
          };
        }

        return post;
      })
    );
  }

  toggleLike(postId: string) {

    this.posts.update(posts =>
      posts.map(post => {

        if (post.id === postId) {

          return {
            ...post,
            likes: post.likes + 1
          };
        }

        return post;
      })
    );
  }
}

